<?php require '../config/database.php'; require_once '../config/auth.php'; require_role('user'); $uid=$_SESSION['user_id']; $m=mysqli_fetch_assoc(mysqli_query($conn,"SELECT * FROM members WHERE user_id=$uid")); $member_id=$m['id']; if($_SERVER['REQUEST_METHOD']=='POST'){ $date=$_POST['date'];$s=(int)$_POST['systolic'];$d=(int)$_POST['diastolic'];$hr=(int)$_POST['heart_rate'];$temp=(float)$_POST['temperature'];$sugar=(float)$_POST['blood_sugar'];$oxy=(int)$_POST['oxygen'];$w=(float)$_POST['weight'];$bmi=$m['height_cm']>0?round($w/pow($m['height_cm']/100,2),2):0;$status=bp_category($s,$d);$notes=mysqli_real_escape_string($conn,$_POST['notes']); mysqli_query($conn,"INSERT INTO health_records(member_id,record_date,systolic,diastolic,heart_rate,temperature,blood_sugar,oxygen_level,weight_kg,bmi,status,notes) VALUES($member_id,'$date',$s,$d,$hr,$temp,$sugar,$oxy,$w,$bmi,'$status','$notes')"); mysqli_query($conn,"UPDATE members SET weight_kg=$w WHERE id=$member_id"); } $rows=mysqli_query($conn,"SELECT * FROM health_records WHERE member_id=$member_id ORDER BY record_date DESC"); ?>
<!DOCTYPE html><html><head><title>Health Records</title><link rel="stylesheet" href="../assets/css/style.css"><script src="../assets/js/app.js"></script></head><body><div class="layout"><?php include '_nav.php'; ?><main class="main"><h1>Medical & Fitness Record System</h1><form class="form" method="post"><div class="three"><div><label>Date</label><input type="date" name="date" value="<?=date('Y-m-d')?>"></div><div><label>Systolic</label><input id="systolic" name="systolic" oninput="bpCalc()"></div><div><label>Diastolic</label><input id="diastolic" name="diastolic" oninput="bpCalc()"></div></div><div id="bpResult" class="badge"></div><div class="three"><div><label>Heart Rate</label><input name="heart_rate"></div><div><label>Temperature</label><input name="temperature" step=".1"></div><div><label>Blood Sugar</label><input name="blood_sugar" step=".1"></div></div><div class="two"><div><label>Oxygen Level</label><input name="oxygen"></div><div><label>Weight kg</label><input name="weight" value="<?=$m['weight_kg']?>" step=".1"></div></div><label>Notes</label><textarea name="notes"></textarea><button>Save Health Record</button></form><br><table class="table"><tr><th>Date</th><th>BP</th><th>Heart</th><th>Sugar</th><th>Temp</th><th>Oxygen</th><th>BMI</th><th>Status</th></tr><?php while($r=mysqli_fetch_assoc($rows)):?><tr><td><?=$r['record_date']?></td><td><?=$r['systolic']?>/<?=$r['diastolic']?></td><td><?=$r['heart_rate']?></td><td><?=$r['blood_sugar']?></td><td><?=$r['temperature']?></td><td><?=$r['oxygen_level']?>%</td><td><?=$r['bmi']?> <?=bmi_category($r['bmi'])?></td><td><span class="badge"><?=e($r['status'])?></span></td></tr><?php endwhile;?></table></main></div></body></html>
